        // ── RAM PAGE INIT ─────────────────────────────────────────────────────
        private async Task LoadRamPageAsync()
        {
            try
            {
                await Dispatcher.InvokeAsync(() =>
                {
                    try
                    {
                        if (FindName("RamLiveContainer") is System.Windows.Controls.Border liveContainer
                            && liveContainer.Child == null)
                        {
                            var pie = new RamLivePanel { Margin = new Thickness(0) };
                            liveContainer.Child = pie;
                        }
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "LoadRamPageAsync.RamLivePanel"); }
                    StartRamCards(); // the "Memory usage" card (MainWindow.RamPage.cs)
                });

                if (_ramModules.Count == 0)
                    _ramModules = await _hwService.GetRamAsync();
                var modules = _ramModules;
                if (modules.Count == 0) return;

                SMDWin.Services.RamTimings? ramTimings = null;
                try { ramTimings = await SMDWin.Services.RamDiagnosticsService.GetTimingsAsync(modules); }
                catch (Exception ex) { AppLogger.Debug("GetTimingsAsync: " + ex.Message); }

                await Dispatcher.InvokeAsync(() =>
                {
                    try
                    {
                        var channelInfo = SMDWin.Services.RamDiagnosticsService.DetectChannelMode(modules);
                        bool isDual = channelInfo.Status == SMDWin.Services.DualChannelStatus.DualChannel
                                   || channelInfo.Status == SMDWin.Services.DualChannelStatus.QuadChannel;
                        if (TxtRamTotalConf != null)
                        {
                            ulong totalBytes = (ulong)modules.Where(m => !m.IsEmpty).Sum(m => (long)m.CapacityBytes);
                            TxtRamTotalConf.Text = totalBytes > 0 ? $"{totalBytes / 1_073_741_824.0:0.#} GB" : "—";
                        }
                        bool solderedRam = IsSolderedRam(modules);
                        if (TxtRamChannel != null && solderedRam)
                        {
                            // soldered memory: the channels are on the board, nothing to add or move — no single / dual advice
                            int ch = modules.Count(m => !m.IsEmpty);
                            TxtRamChannel.Text = PT("On the board · {0} channels", ch);
                            TxtRamChannel.ToolTip = PT("The memory chips are soldered on the motherboard; Windows reports each channel separately.");
                            TxtRamChannel.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextPrimaryBrush");
                        }
                        else if (TxtRamChannel != null)
                        {
                            TxtRamChannel.Text = channelInfo.Status switch
                            {
                                SMDWin.Services.DualChannelStatus.QuadChannel => "Quad Channel",
                                SMDWin.Services.DualChannelStatus.DualChannel => "Dual Channel",
                                SMDWin.Services.DualChannelStatus.FlexMode    => "Flex Mode",
                                SMDWin.Services.DualChannelStatus.SingleChannel => "Single Channel",
                                _                                             => "Not reported",
                            };
                            TxtRamChannel.ToolTip = channelInfo.Description;
                            TxtRamChannel.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty,
                                channelInfo.Status == SMDWin.Services.DualChannelStatus.SingleChannel ? "StatusWarnBrush" : "TextPrimaryBrush");
                        }
                        if (FindName("TxtRamChannelAdvice") is System.Windows.Controls.TextBlock chAdv)
                        {
                            if (isDual || solderedRam || string.IsNullOrEmpty(channelInfo.Advice))
                            {
                                chAdv.Text = "";
                                chAdv.Visibility = Visibility.Collapsed;
                            }
                            else
                            {
                                chAdv.Text = channelInfo.Advice;
                                chAdv.Visibility = Visibility.Visible;
                            }
                        }
                        var firstMod = modules.FirstOrDefault(m => !string.IsNullOrEmpty(m.Speed));
                        if (firstMod != null)
                        {
                            // the speed the memory runs at now (configured); the rated speed of the module / chips goes in the tooltip
                            // (LPDDR5X: "8533" configured vs "8000" reported by the chips — the old text showed one and cut the other)
                            if (FindName("TxtRamSpeedConf") is System.Windows.Controls.TextBlock spd)
                            {
                                spd.Text = firstMod.ConfiguredMHz > 0 ? firstMod.ConfiguredMHz.ToString()
                                         : firstMod.Speed.Contains("MHz", StringComparison.OrdinalIgnoreCase) ? firstMod.Speed.Replace("MHz", "").Trim() : firstMod.Speed;
                                spd.ToolTip = firstMod.RatedMHz > 0 && firstMod.ConfiguredMHz > 0 && firstMod.RatedMHz != firstMod.ConfiguredMHz
                                    ? PT("Runs at {0} MHz · the module reports {1} MHz", firstMod.ConfiguredMHz, firstMod.RatedMHz) : null;
                            }
                            // the type is already in the Modules card; a long one (LPDDR5X) pushed the speed out of the column
                            if (FindName("TxtRamSpeedRated") is System.Windows.Controls.TextBlock spdR)
                                spdR.Text = string.IsNullOrEmpty(firstMod.MemoryType) || firstMod.MemoryType.Length > 4 ? "" : $"· {firstMod.MemoryType}";
                        }
                        if (TxtRamTimings != null)
                        {
                            TxtRamTimings.Text = ramTimings != null && ramTimings.CL > 0
                                ? $"CL{ramTimings.CL}-{ramTimings.TRCD}-{ramTimings.TRP}-{ramTimings.TRAS}"
                                : "—";
                        }
                        if (firstMod != null)
                        {
                            if (TxtRamVoltage != null)
                            {
                                if (firstMod.VoltageV > 0)
                                {
                                    TxtRamVoltage.Text = $"{firstMod.VoltageV:F2} V";
                                    TxtRamVoltage.ToolTip = null;
                                }
                                else
                                {
                                    double typical = firstMod.MemoryType switch
                                    {
                                        "DDR5" => 1.1, "DDR4" => 1.2, "DDR3" => 1.5, "DDR2" => 1.8, _ => 0
                                    };
                                    TxtRamVoltage.Text = typical > 0 ? $"~{typical:F2} V" : "—";
                                    TxtRamVoltage.ToolTip = typical > 0
                                        ? PT("Not reported by BIOS/SMBIOS on this system — showing the typical voltage for this memory generation, not a real reading.")
                                        : null;
                                }
                            }
                            if (FindName("TxtRamVoltageRange") is System.Windows.Controls.TextBlock voltR)
                                voltR.Text = (firstMod.MinVoltageV > 0 && firstMod.MaxVoltageV > firstMod.MinVoltageV)
                                    ? PT("range {0}–{1} V", firstMod.MinVoltageV.ToString("F2"), firstMod.MaxVoltageV.ToString("F2")) : "";

                            // ECC — IsEcc already computed in HardwareService (TotalWidth > DataWidth).
                            if (TxtRamEcc != null)
                            {
                                TxtRamEcc.Text = firstMod.IsEcc ? "✓ ECC" : "Non-ECC";
                                TxtRamEcc.Foreground = firstMod.IsEcc
                                    ? (System.Windows.Media.Brush)FindResource("StatusOkBrush")
                                    : (System.Windows.Media.Brush)FindResource("TextSecondaryBrush");
                            }

                            // XMP/EXPO — Windows does not say directly whether the profile is active in the BIOS.
                            // Estimate: if the configured speed >= the module's maximum SPD speed (RatedMHz), the overclock profile is most likely
                            // active — a module running EXACTLY at its maximum factory speed without XMP would be a very rare coincidence (base
                            // JEDEC is almost always below the "rated" speed on the label).
                            bool solderedMem = (firstMod.MemoryType ?? "").StartsWith("LPDDR", StringComparison.OrdinalIgnoreCase);
                            if (solderedMem && FindName("BorderRamXmp") is System.Windows.Controls.Border xmpS
                                && FindName("TxtRamXmp") is System.Windows.Controls.TextBlock xmpTS)
                            {
                                // soldered LPDDR has no XMP / EXPO profiles: it runs at the speed set by the laptop maker
                                xmpTS.Text = PT("Not applicable");
                                xmpTS.ToolTip = PT("Soldered LPDDR memory runs at the speed set by the laptop maker; it has no XMP / EXPO profiles.");
                                xmpTS.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                                xmpS.Visibility = Visibility.Visible;
                            }
                            else if (firstMod.RatedMHz > 0 && firstMod.ConfiguredMHz > 0
                                && FindName("BorderRamXmp") is System.Windows.Controls.Border xmpBorder
                                && FindName("TxtRamXmp") is System.Windows.Controls.TextBlock xmpTxt)
                            {
                                bool likelyXmp = firstMod.ConfiguredMHz >= firstMod.RatedMHz;
                                xmpTxt.Text = likelyXmp ? LanguageService.S("Ram", "XmpLikelyActive")
                                                         : LanguageService.S("Ram", "JedecStandardSpeed");
                                xmpTxt.Foreground = likelyXmp
                                    ? (System.Windows.Media.Brush)FindResource("AccentBrush")
                                    : (System.Windows.Media.Brush)FindResource("TextSecondaryBrush");
                                xmpBorder.Visibility = Visibility.Visible;
                            }
                            else if (FindName("BorderRamXmp") is System.Windows.Controls.Border xmpB2
                                  && FindName("TxtRamXmp") is System.Windows.Controls.TextBlock xmpT2)
                            {
                                // Without the SPD / configured speed we cannot estimate — say so instead of leaving the column empty
                                xmpT2.Text = PT("Not reported");
                                xmpT2.ToolTip = PT("The BIOS does not report the module's rated speed, so XMP/EXPO status can't be estimated. Older systems (DDR3) usually have no XMP profile in use.");
                                xmpT2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                                xmpB2.Visibility = Visibility.Visible;
                            }
                        }
                        BuildRamSlotDiagram(modules);
                        BuildRamSlotTiles(modules); // the slots as blocks (the "Modules" card)
                        if (FindName("RamGrid") is System.Windows.Controls.DataGrid dg)
                        {
                            var installed = modules.Where(m => !m.IsEmpty).ToList();
                            dg.ItemsSource = new System.Collections.ObjectModel.ObservableCollection<RamEntry>(installed);

                            if (FindName("ColRamEcc") is DataGridColumn eccCol)
                                eccCol.Visibility = installed.Count > 0 && installed.All(m => string.IsNullOrEmpty(m.IsEccDisplay))
                                    ? Visibility.Collapsed : Visibility.Visible;
                            if (FindName("ColRamVoltage") is DataGridColumn vCol)
                                vCol.Visibility = installed.Count > 0 && installed.All(m => m.VoltageDisplay == "—")
                                    ? Visibility.Collapsed : Visibility.Visible;
                        }

                        try
                        {
                            var (vulnerable, rhInfo, rhMitigation) =
                                SMDWin.Services.RamDiagnosticsService.GetRowhammerInfo(modules);
                            if (FindName("TxtRowhammerStatus") is System.Windows.Controls.TextBlock rhStatus)
                            {
                                rhStatus.Text = "Rowhammer: " + (vulnerable
                                    ? _LS("Ram", "PotentiallyVulnerable")
                                    : _LS("Ram", "LowRisk"));
                            }
                            if (FindName("TxtRowhammerIcon") is System.Windows.Controls.TextBlock rhIcon)
                                rhIcon.Text = vulnerable ? "⚠" : "✓";
                            if (FindName("RowhammerRow") is FrameworkElement rhRow)
                            {
                                string tip = string.Join("\n\n", new[] { rhInfo, rhMitigation }.Where(s => !string.IsNullOrEmpty(s)));
                                rhRow.ToolTip = string.IsNullOrEmpty(tip) ? null : tip;
                            }
                            // A short explanation under the status: "vulnerable" does not mean faulty.
                            if (FindName("TxtRowhammerExplain") is System.Windows.Controls.TextBlock rhEx)
                                rhEx.Text = vulnerable
                                    ? "A theoretical security weakness of older memory types (DDR3/DDR4 without extra protection). It is not a defect and does not affect stability or normal use."
                                    : "This memory has built-in protection (DDR5 on-die ECC or ECC modules).";
                        }
                        catch (Exception ex) { AppLogger.Warning(ex, "LoadRamPageAsync.Rowhammer"); }
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "LoadRamPageAsync.UI"); }
                });
            }
            catch (Exception ex) { AppLogger.Warning(ex, "LoadRamPageAsync"); }

            // start the RAM Top processes table (refresh 5s)
            StartRamProcTimer();
        }

        // ════════════════════════════════════════════════════════════════════
        // Top processes by RAM — table + context menu
        // ════════════════════════════════════════════════════════════════════
        private void StartRamProcTimer()
        {
            _ = RefreshRamProcessesAsync(); // populate immediately
            if (_ramProcTimer == null)
            {
                _ramProcTimer = new System.Windows.Threading.DispatcherTimer
                {
                    Interval = TimeSpan.FromSeconds(5)
                };
                _ramProcTimer.Tick += async (_, _) => await RefreshRamProcessesAsync();
            }
            _ramProcTimer.Start();
        }

        private void StopRamProcTimer() => _ramProcTimer?.Stop();

        private async Task RefreshRamProcessesAsync()
        {
            try
            {
                var snap = await _procMonitor.GetSnapshotAsync(15);
                await Dispatcher.InvokeAsync(() =>
                {
                    // the whole list (not only the first 15), so the list in the card can fill the height
                    UpdateRamTopList(BuildGrouped(snap.AllProcesses is { Count: > 0 } all ? all : snap.TopByRam, snap.UsedRamMB));
                });
            }
            catch (Exception ex) { AppLogger.Warning(ex, "RefreshRamProcessesAsync"); }
        }

        // Builds the list grouped by exe — multiple instances → a single row
        private static List<SMDWin.Models.GroupedProcessEntry> BuildGrouped(
            List<ProcessEntry> source, long usedRamMB)
        {
            float systemRam = Math.Max(1, usedRamMB);
            return source
                .GroupBy(p => p.Name.ToLowerInvariant())
                .Select(g =>
                {
                    var instances = g.ToList();
                    var first = instances.First();
                    string display = !string.IsNullOrWhiteSpace(first.Description)
                        ? first.Description : first.Name;
                    float totalRam = instances.Sum(p => p.RamMB);
                    float totalCpu = instances.Sum(p => p.CpuPct);
                    return new SMDWin.Models.GroupedProcessEntry
                    {
                        ExeName       = first.Name,
                        DisplayName   = display,
                        TotalRamMB    = totalRam,
                        TotalCpuPct   = totalCpu,
                        InstanceCount = instances.Count,
                        Pid           = first.Pid,
                        AllPids       = instances.Select(p => p.Pid).ToList(),
                        Children      = instances, // sub-processes for expand
                        RamFraction   = totalRam / systemRam,
                        CpuFraction   = Math.Min(1.0, totalCpu / 100.0)
                    };
                })
                .OrderByDescending(g => g.TotalRamMB)
                .ToList();
        }


        // ── Shared helper: opens ProcessAnalyzerWindow for a PID ──────────
        private void OpenProcessAnalyzer(int pid, string name)
        {
            try
            {
                var win = new SMDWin.Views.ProcessAnalyzerWindow(pid, name) { Owner = this };
                SMDWin.Views.Ui.FixOwnedWindowMinimize(win, this);
                SMDWin.Services.ThemeManager.Apply(
                    SMDWin.Services.SettingsService.Current.ThemeName == "Auto"
                        ? SMDWin.Services.ThemeManager.ResolveAuto()
                        : SMDWin.Services.SettingsService.Current.ThemeName,
                    win.Resources);
                win.Show();
            }
            catch (Exception ex) { AppLogger.Debug($"OpenProcessAnalyzer: {ex.Message}"); }
        }

        private double ComputeRamStickScale()
        {
            double h = this.ActualHeight;
            if (h <= 0) return 1.0; // the window has not been measured yet (first render) — start from the full size
            const double fullAt   = 950;  // >= this: a large screen or normal scaling -> the full drawing (150px)
            const double minAt    = 680;  // <= this: the smallest realistic case (14" at 150%) -> minimum
            const double minScale = 0.62; // 150 * 0.62 ≈ 93px — still recognisable as a "RAM stick"
            if (h >= fullAt) return 1.0;
            if (h <= minAt) return minScale;
            double t = (h - minAt) / (fullAt - minAt);
            return minScale + t * (1.0 - minScale);
        }

        private bool _powerAdvGuard = false;
        private bool _powerAdvUserControlled = false;
        internal void ExpAdvancedPower_UserToggled(object sender, RoutedEventArgs e)
        {
            if (!_powerAdvGuard) _powerAdvUserControlled = true;
        }
        internal void PanelBattery_ScrollChanged(object sender, System.Windows.Controls.ScrollChangedEventArgs e)
        {
            if (_powerAdvGuard || _powerAdvUserControlled) return;
            if (PanelBattery == null) return;
            if (FindName("ExpAdvancedPower") is not System.Windows.Controls.Expander exp) return;
            try
            {
                _powerAdvGuard = true;
                double viewport = PanelBattery.ViewportHeight;
                double extent   = PanelBattery.ExtentHeight;
                if (viewport <= 0 || extent <= 0) return;
                double slack = viewport - extent;

                if (slack < -10 && exp.IsExpanded) { exp.IsExpanded = false; return; }
            }
            finally { _powerAdvGuard = false; }
        }

        private double _lastRamStickScaleApplied = -1;
        private void RamStickDiagram_SizeChanged(object sender, System.Windows.SizeChangedEventArgs e)
        {
            if (_ramModules == null || _ramModules.Count == 0) return;
            if (RamSlotsPanel == null || RamSlotsPanel.Children.Count == 0) return;
            double s = ComputeRamStickScale();
            if (Math.Abs(s - _lastRamStickScaleApplied) < 0.03) return;
            BuildRamSlotDiagram(_ramModules);
        }

        // The upgrade information (slots, maximum, compatible type) is in the Configuration card / the module table.


        private void BuildRamSlotDiagram(List<RamEntry> modules)
        {
            RamSlotsPanel.Children.Clear();
            _ramStickBorders.Clear();
            _ramStickEffects.Clear();
            double ramStickScale = ComputeRamStickScale();
            _lastRamStickScaleApplied = ramStickScale;

            // The real number of physical slots — SMBIOS (Type 17) is the most accurate source.
            // If SMBIOS reports more slots than the WMI list has, fill in empty slots so the diagram matches the board exactly
            // (e.g. 8 slots, 2 occupied → show 8).
            int smbiosSlots = _smbiosInfo?.TotalSlots ?? 0;
            if (smbiosSlots > modules.Count)
            {
                int toAdd = smbiosSlots - modules.Count;
                for (int k = 0; k < toAdd; k++)
                {
                    modules.Add(new RamEntry
                    {
                        BankLabel = $"Slot {modules.Count + 1}",
                        Manufacturer = "—", PartNumber = "—", Capacity = "—",
                        Speed = "—", MemoryType = "—", FormFactor = "—",
                        IsEmpty = true,
                    });
                }
            }

            if (modules.Count == 0) { TxtRamSlotInfo.Text = "No RAM modules detected."; return; }

            // Header: cate sloturi populate / total
            int populatedCount = modules.Count(m => !m.IsEmpty);
            if (FindName("TxtRamSlots") is System.Windows.Controls.TextBlock slotsHdr)
                slotsHdr.Text = $"{populatedCount} / {modules.Count} populated";

            if (FindName("TxtRamSlotInfo") is System.Windows.Controls.TextBlock slotInfoTb && modules.Count > 4)
                slotInfoTb.Text = $"Hover a module for details  ·  {modules.Count} memory devices reported — on systems with on-package/soldered memory (e.g. Intel Lunar Lake), these represent internal channels, not swappable physical slots.";

            var mbBorder = new Border
            {
                Background   = new SolidColorBrush(WpfColor.FromArgb(40, 100, 120, 180)),
                BorderBrush  = new SolidColorBrush(WpfColor.FromArgb(80, 100, 140, 220)),
                BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(8),
                Padding = new Thickness(16, 12, 16, 12),
                HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                VerticalAlignment   = VerticalAlignment.Center,
            };

            var slotsRow = new System.Windows.Controls.WrapPanel
            {
                Orientation = System.Windows.Controls.Orientation.Horizontal,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                MaxWidth = 560,  // ~8 slots (62px + margins) will be laid out on 2 rows
            };
            int maxSlots = modules.Count;
            string chartGreenHex = ThemeManager.IsLight(SettingsService.Current.ThemeName) ? "#16A34A" : "#22C55E";
            var channelColorMap = new Dictionary<char, string> { ['A'] = "#3B82F6", ['B'] = chartGreenHex, ['C'] = "#F59E0B", ['D'] = "#8B5CF6" };
            bool allChannelsKnown = modules.Where(m => !m.IsEmpty).All(m => TryGetChannelLetter(m.SlotLabel) != null);

            for (int i = 0; i < maxSlots; i++)
            {
                var mod = modules[i];
                bool populated = !mod.IsEmpty;
                char? channelLetter = populated ? TryGetChannelLetter(mod.SlotLabel) : null;
                string slotColorHex = allChannelsKnown && channelLetter.HasValue && channelColorMap.TryGetValue(channelLetter.Value, out var cc)
                    ? cc : "#3B82F6"; // neutral — a single accent when the channel is not known for sure
                var slotContainer = new StackPanel { Margin = new Thickness(10 * ramStickScale, 6 * ramStickScale, 10 * ramStickScale, 6 * ramStickScale) };

                slotContainer.Children.Add(new TextBlock
                {
                    Text = !string.IsNullOrWhiteSpace(mod.SlotLabel) ? mod.SlotLabel
                         : !string.IsNullOrWhiteSpace(mod.BankLabel) ? mod.BankLabel
                         : $"Slot {i + 1}",
                    FontSize = Ui.FontS, FontWeight = FontWeights.SemiBold,
                    Foreground = (Brush)TryFindResource("TextSecondaryBrush") ?? System.Windows.Media.Brushes.LightGray,
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                    Margin = new Thickness(0, 0, 0, 2),
                    TextTrimming = TextTrimming.CharacterEllipsis, MaxWidth = 62,
                });

                var capacityText = new TextBlock
                {
                    Text = populated ? $"{mod.Capacity} {mod.MemoryType}".Trim() : "",
                    FontSize = Ui.FontS, FontWeight = FontWeights.SemiBold,
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                    TextAlignment = TextAlignment.Center, TextWrapping = TextWrapping.NoWrap,
                    TextTrimming = TextTrimming.CharacterEllipsis, MaxWidth = 62,
                    Margin = new Thickness(0, 0, 0, 1),
                    Foreground = (Brush)TryFindResource("TextPrimaryBrush") ?? System.Windows.Media.Brushes.White,
                    Visibility = populated ? Visibility.Visible : Visibility.Hidden,
                };
                slotContainer.Children.Add(capacityText);

                var speedText = new TextBlock
                {
                    Text = populated ? mod.Speed : "—",
                    FontSize = Ui.FontS, FontWeight = FontWeights.SemiBold,
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                    TextAlignment = TextAlignment.Center, TextWrapping = TextWrapping.NoWrap,
                    TextTrimming = TextTrimming.CharacterEllipsis, MaxWidth = 62,
                    Margin = new Thickness(0, 0, 0, 6),
                    Foreground = (Brush)TryFindResource("TextPrimaryBrush") ?? System.Windows.Media.Brushes.White,
                    Visibility = populated ? Visibility.Visible : Visibility.Hidden,
                };
                slotContainer.Children.Add(speedText);

                double stickW = 62 * ramStickScale, stickH = 150 * ramStickScale;
                var stickGrid = new Grid { Width = stickW, Height = stickH };

                var stick = new Border
                {
                    Width = stickW, Height = stickH,
                    CornerRadius = new CornerRadius(4, 4, 4, 4),
                    Cursor = System.Windows.Input.Cursors.Hand,
                    UseLayoutRounding = true,
                    SnapsToDevicePixels = true,
                };
                _ramStickBorders.Add(stick);   // store ref for animation
                // Pre-create DropShadowEffect to reuse in animation (avoids creating on every tick)
                var stickEffect = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color       = WpfColor.FromRgb(34, 211, 238),
                    BlurRadius  = 8,
                    ShadowDepth = 0,
                    Opacity     = 0.5,
                };
                stick.Effect = stickEffect;
                _ramStickEffects.Add(stickEffect);

                if (populated)
                {
                    var gradColor = (WpfColor)WpfColorConv.ConvertFromString(slotColorHex)!;
                    stick.Background = new System.Windows.Media.LinearGradientBrush(
                        WpfColor.FromArgb(220, (byte)(gradColor.R * 0.4), (byte)(gradColor.G * 0.4), (byte)(gradColor.B * 0.4)),
                        WpfColor.FromArgb(220, (byte)(gradColor.R * 0.7), (byte)(gradColor.G * 0.7), (byte)(gradColor.B * 0.7)), 0);
                    stick.BorderBrush     = new SolidColorBrush(gradColor);
                    stick.BorderThickness = new Thickness(1.5);

                    double innerW = 59 * ramStickScale, innerH = 147 * ramStickScale;
                    var stickContent = new Canvas
                    {
                        Width = innerW, Height = innerH, // the real interior: 62-2×1.5 × 150-2×1.5, scaled
                        UseLayoutRounding = true,
                        SnapsToDevicePixels = true,
                    };
                    double stickCenterX = innerW / 2;
                    double lineW = 34 * ramStickScale, lineH = Math.Max(1.5, 2 * ramStickScale), lineGap = 5 * ramStickScale;
                    const int lineCountTop = 4, lineCountBottom = 4;
                    double linesTopH    = lineCountTop    * lineH + (lineCountTop    - 1) * lineGap;
                    double linesBottomH = lineCountBottom * lineH + (lineCountBottom - 1) * lineGap;

                    double chipW = 24 * ramStickScale, chipH = 14 * ramStickScale, chipGap = 6 * ramStickScale;
                    const int chipCount = 4;
                    double chipsBlockH = chipCount * chipH + (chipCount - 1) * chipGap;

                    double groupGap = 10 * ramStickScale;
                    double totalContentH = linesTopH + groupGap + chipsBlockH + groupGap + linesBottomH;
                    double startY = (innerH - totalContentH) / 2; // symmetric top/bottom by construction, at any scale

                    var lineBrush = new SolidColorBrush(WpfColor.FromArgb(60, 200, 220, 255));
                    for (int l = 0; l < lineCountTop; l++)
                    {
                        var lineEl = new Border
                        {
                            Width = lineW, Height = lineH,
                            Background = lineBrush,
                            UseLayoutRounding = true,
                            SnapsToDevicePixels = true,
                        };
                        Canvas.SetLeft(lineEl, stickCenterX - lineW / 2);
                        Canvas.SetTop(lineEl, startY + l * (lineH + lineGap));
                        stickContent.Children.Add(lineEl);
                    }

                    double chipsStartY = startY + linesTopH + groupGap;
                    var chipFill = new SolidColorBrush(WpfColor.FromArgb(180, 20, 30, 50));
                    var chipBorder = new SolidColorBrush(gradColor);
                    for (int c = 0; c < chipCount; c++)
                    {
                        var chipEl = new Border
                        {
                            Width = chipW, Height = chipH,
                            Background = chipFill, BorderBrush = chipBorder,
                            BorderThickness = new Thickness(0.5), CornerRadius = new CornerRadius(1.5),
                            UseLayoutRounding = true,
                            SnapsToDevicePixels = true,
                        };
                        Canvas.SetLeft(chipEl, stickCenterX - chipW / 2);
                        Canvas.SetTop(chipEl, chipsStartY + c * (chipH + chipGap));
                        stickContent.Children.Add(chipEl);
                    }

                    double linesBottomStartY = chipsStartY + chipsBlockH + groupGap;
                    for (int l = 0; l < lineCountBottom; l++)
                    {
                        var lineEl = new Border
                        {
                            Width = lineW, Height = lineH,
                            Background = lineBrush,
                            UseLayoutRounding = true,
                            SnapsToDevicePixels = true,
                        };
                        Canvas.SetLeft(lineEl, stickCenterX - lineW / 2);
                        Canvas.SetTop(lineEl, linesBottomStartY + l * (lineH + lineGap));
                        stickContent.Children.Add(lineEl);
                    }
                    stick.Child = stickContent;
                    string slotDisplayName = !string.IsNullOrWhiteSpace(mod.SlotLabel) ? mod.SlotLabel
                                            : !string.IsNullOrWhiteSpace(mod.BankLabel) ? mod.BankLabel
                                            : $"Slot {i + 1}";
                    stick.ToolTip = new ToolTip { Content = $"{slotDisplayName}: {mod.Capacity}  {mod.MemoryType}  {mod.Speed}\n{mod.Manufacturer} — {mod.PartNumber}" };

                    int capturedI = i;
                    stick.MouseEnter += (_, _) =>
                    {
                        if (!_ramTestRunning)
                            stick.RenderTransform = new System.Windows.Media.ScaleTransform(1.05, 1.05) { CenterX = stickW / 2, CenterY = stickH / 2 };
                        string hoverInfo = $"{slotDisplayName}: {mod.Capacity}  {mod.MemoryType} @ {mod.Speed}  •  {mod.Manufacturer}  •  {mod.PartNumber}";
                        TxtRamSlotInfo.Text = hoverInfo;
                        TxtRamSlotInfo.ToolTip = hoverInfo;
                    };
                    stick.MouseLeave += (_, _) =>
                    {
                        stick.RenderTransform = null;
                        TxtRamSlotInfo.ToolTip = null;
                        TxtRamSlotInfo.Text = SettingsService.Current.Language switch
                        {
                            "ro" => "Hover pe un modul pentru detalii",
                            "de" => "Bewegen Sie die Maus über ein Modul für Details",
                            "fr" => "Survolez un module pour plus de détails",
                            _    => "Hover over a module for details",
                        };
                    };
                }
                else
                {
                    stick.Background      = new SolidColorBrush(WpfColor.FromArgb(30, 100, 110, 140));
                    stick.BorderBrush     = new SolidColorBrush(WpfColor.FromArgb(50, 120, 130, 160));
                    stick.BorderThickness = new Thickness(1);
                    stick.Child = new TextBlock
                    {
                        Text = "Empty", FontSize = 9,
                        VerticalAlignment   = VerticalAlignment.Center,
                        HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                        Foreground = new SolidColorBrush(WpfColor.FromArgb(80, 150, 160, 180)),
                    };
                }

                // Result overlay — hidden until test finishes
                var resultOverlay = new Border
                {
                    Name              = $"RamResult_{i}",
                    CornerRadius      = new CornerRadius(0, 0, 4, 4),
                    Visibility        = Visibility.Collapsed,
                    Background        = new SolidColorBrush(WpfColor.FromArgb(190, 0, 0, 0)),
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Stretch,
                    VerticalAlignment   = VerticalAlignment.Bottom,
                    Padding           = new Thickness(4, 3, 4, 3),
                    Child             = new TextBlock
                    {
                        Name              = $"RamResultTxt_{i}",
                        Text              = "",
                        FontSize          = Ui.FontS,
                        FontWeight        = FontWeights.Bold,
                        TextAlignment     = TextAlignment.Center,
                        HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                        Foreground        = System.Windows.Media.Brushes.White,
                    },
                };

                stickGrid.Children.Add(stick);
                stickGrid.Children.Add(resultOverlay);
                slotContainer.Children.Add(stickGrid);

                slotContainer.Children.Add(new TextBlock
                {
                    Text = allChannelsKnown && channelLetter.HasValue ? $"Ch {channelLetter}" : "",
                    Visibility = allChannelsKnown && channelLetter.HasValue ? Visibility.Visible : Visibility.Collapsed,
                    FontSize = 9,
                    HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                    Margin = new Thickness(0, 3, 0, 0),
                    Foreground = new SolidColorBrush(WpfColor.FromArgb(120,
                        channelLetter == 'A' ? (byte)100 : (byte)50,
                        channelLetter == 'A' ? (byte)150 : (byte)200, 255)),
                });

                slotsRow.Children.Add(slotContainer);
            }

            mbBorder.Child = slotsRow;
            RamSlotsPanel.Children.Add(mbBorder);

            // Channel mode — shown in the dedicated card above, not here too
            TxtRamSlotInfo.Text = LanguageService.S("Ram", "SlotHoverHint");
        }
    }
}
